#!/bin/sh
# bid form helper on the tender-portal tab, addressing controls by their label instead of refs:
#   w pick <select label> <option>     choose and press "Auswahl übernehmen"
#   w set <select label> <option>      choose only
#   w type <textbox label> <text>      fill a field
#   w tick <checkbox label>            tick a box
#   w press <button label>             click a button
#   w show                             print the form part of the page
D=/Users/akshatkhair/.claude/jobs/71c86c9d/tmp/d
T=${TAB:-tender-portal}
ref() { $D "$T" look | grep -o "\[e[0-9]* $1 \"$2" | head -1 | grep -o 'e[0-9][0-9]*' | head -1; }
short() { sed -n '/^## /,$p' | sed 's/ | 4 Wochen.*52 Wochen\]/ | ... 52 Wochen]/' | cut -c1-${WIDTH:-330}; }
case "$1" in
  pick) $D "$T" select "$(ref select "$2")" "$3" >/dev/null; $D "$T" click "$(ref button "Auswahl übernehmen")" | short ;;
  set) $D "$T" select "$(ref select "$2")" "$3" | short ;;
  type) $D "$T" fill "$(ref textbox "$2")" "$3" >/dev/null ;;
  tick) $D "$T" check "$(ref checkbox "$2")" >/dev/null ;;
  press) $D "$T" click "$(ref button "$2")" | short ;;
  show) $D "$T" look | short ;;
esac

